import{z as n,x as s,o as r,c as p,q as t,j as B,D as a,d as o,s as A,S as i,b as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"rollout 引擎的架构","description":"","frontmatter":{"title":"rollout 引擎的架构","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rlsys-rollout-arch.md","filePath":"llm/rlsys-rollout-arch.md","lastUpdated":1791413859000}'),d={name:"llm/rlsys-rollout-arch.md"};function C(m,E,h,F,u,D){const e=s("Mermaid");return r(),p("div",null,[E[2]||(E[2]=t('<h1 id="rollout-引擎的架构" tabindex="-1">rollout 引擎的架构 <a class="header-anchor" href="#rollout-引擎的架构" aria-label="Permalink to &quot;rollout 引擎的架构&quot;">​</a></h1><div class="epigraph"><p>算法论文写的是一次梯度更新怎么算；训练系统回答的是这次更新每天重复几千次时，样本从哪来、由谁生成、凭什么还算 on-policy。</p><footer>—— 据 Sheng 等 HybridFlow（EuroSys 2025）的抽象分层整理</footer></div><p><a href="/llm/dist-map">上一课</a>把分布式训练收成四本账与八步决策单：状态、通信、时间、故障，同步组是合同、峰值决定生死、恢复时间是有效算力的一部分。训练侧的机器装好了，RL 训练还剩另一半：算法只规定「拿到一批样本之后怎么更新」，没有规定样本由谁生成。本课程开卷 RL 训练系统：把算法装成一台机器。第一个零件是 rollout 引擎——把提示批变成经验批的部件，本课程其余课默认已读完本课给出的接口定义。</p><p><span class="marginnote">「rollout」翻译成大白话：让模型按当前策略往下生成一整条回答的过程，像下棋时「往前推演一盘」。训练机把它当成专门部件：你给它一批提示和一版权重，它还你一批「序列 + 每个 token 生成当时的概率」，这批产出就叫经验。</span></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>训练器自带 <code>generate</code>，为什么还要一个专门的 rollout 引擎？因为两种负载的最优布局相反。训练布局为前向反向设计：3D 并行、激活重计算、优化器状态分片；生成负载是自回归逐 token，吃 KV cache、连续批处理与大显存占用，这些是推理引擎的本行。让训练布局兼职生成，每步都要跨流水线传递缓存，或干脆不做 cache，吞吐差一个量级。于是系统分裂成两个角色，缺口随之出现：两者的边界划在哪，接口传什么，权重如何从训练侧流到生成侧而不出错。这些问题答错的代价不是慢，而是静默地不再 on-policy。</p><p><span class="marginnote">数字实例看「布局错了有多亏」：让训练布局兼职生成、不做 KV cache，每出一个 token 都要把整个前缀重新前向一遍——生成 2000 token 的序列，计算量从约 2000 次单步前向膨胀到约 \\(2000^2/2=200\\) 万次 token 计算。慢还只是轻的，静默脱离 on-policy 才是重的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>rollout 引擎的职责契约只有一条：输入提示批与权重版本 \\(v_k\\)，输出响应序列、逐 token 的行为 logprob \\(\\log \\pi_{\\mathrm{beh}}(y_t \\mid y_{\\lt t})\\)，以及结束原因（自然结束或截断）。围绕契约有三个设计决定。第一，放置：与训练器同卡共置，还是独立一组卡分置——共置省卡，但要协调两相的显存峰值；分置吞吐高，要付权重传输与过期（staleness）的账。第二，编排：HybridFlow 用单控制器编排 RL 数据流（谁先生成、谁后打分、谁更新），多控制器执行每个模型的分布式计算；前者好改算法，后者好跑通信。第三，权重同步：全量广播、重切分重组、还是参数服务器拉取，共同要求是原子生效并带版本号。同步协议的细节与坑，<a href="/llm/rollout-weight-sync">rollout 引擎与权重同步</a>已有专课，本课只钉接口。</p><p><span class="marginnote">HybridFlow 论文报告相对既有 RLHF 系统 1.53×–20.57× 的吞吐，倍数强烈依赖基线实现与放置策略；引用时必须带上实验设定，否则不可比。</span></p>',10)),(r(),B(i,null,{default:a(()=>[A(e,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%8F%90%E7%A4%BA%E6%89%B9%22%5D%20--%3E%20ENG%5B%22rollout%20%E5%BC%95%E6%93%8E%EF%BC%88%E7%94%9F%E6%88%90%E5%B8%83%E5%B1%80%EF%BC%8C%E6%9D%83%E9%87%8D%20v_k%EF%BC%89%22%5D%0A%20%20ENG%20--%3E%20SEQ%5B%22%E5%93%8D%E5%BA%94%E5%BA%8F%E5%88%97%20%2B%20%E8%A1%8C%E4%B8%BA%20logprob%20%2B%20%E7%BB%93%E6%9D%9F%E5%8E%9F%E5%9B%A0%22%5D%0A%20%20SEQ%20--%3E%20BUF%5B%22%E7%BB%8F%E9%AA%8C%E7%BC%93%E5%86%B2%22%5D%0A%20%20TR%5B%22%E8%AE%AD%E7%BB%83%E5%99%A8%EF%BC%88%E8%AE%AD%E7%BB%83%E5%B8%83%E5%B1%80%EF%BC%89%22%5D%20--%3E%7C%22%E6%9D%83%E9%87%8D%E5%90%8C%E6%AD%A5%20v_k%EF%BC%8C%E5%8E%9F%E5%AD%90%E7%94%9F%E6%95%88%22%7C%20ENG%0A%20%20BUF%20--%3E%20TR%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[o(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l("h2",{id:"机制",tabindex:"-1"},[o("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=l("p",null,[o("接口里最值钱的一列是行为 logprob。严格 on-policy 时 \\(\\pi_{\\mathrm{beh}}\\) 与当前策略 \\(\\pi_\\theta\\) 相同，重要性权重恒为 1，可以不算；可系统里「相同」是靠版本号对齐维护出来的性质，不是天然成立的事实。生成与更新一旦并发（权重同步有延迟、部分请求还挂在旧引擎上），\\(\\pi_{\\mathrm{beh}}\\) 就落后于 \\(\\pi_\\theta\\)，梯度立刻变成离策略的：不补重要性权重是带偏的估计，补了则引入截断权重的方差（见"),l("a",{href:"/llm/truncated-importance-sampling"},"截断重要性采样"),o("）。所以 rollout 引擎的第一职责不是快，而是让「这批样本是哪个版本的策略生成的」永远可答。工程上由此推出三条铁律：权重同步原子、版本号随样本走、行为 logprob 在生成侧当场算好并缓存，而不是训练时重算冒充。")],-1)),E[5]||(E[5]=l("p",null,[l("span",{class:"marginnote"},"直觉类比：行为 logprob 像小票上的「出厂批次号」——样本在生成那一刻，每个 token 的概率是多少就被当场盖章。训练时若拿最新版策略重算概率冒充小票，等于篡改出厂信息，重要性权重的分母从此对不上，梯度悄悄带偏。")],-1)),(r(),B(i,null,{default:a(()=>[A(e,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%BF%99%E6%89%B9%E6%A0%B7%E6%9C%AC%E6%98%AF%E5%93%AA%E4%B8%AA%E7%89%88%E6%9C%AC%E7%9A%84%E7%AD%96%E7%95%A5%E7%94%9F%E6%88%90%E7%9A%84%EF%BC%9F%22%5D%20--%3E%7C%22%E7%89%88%E6%9C%AC%E4%B8%80%E8%87%B4%EF%BC%9Abeh%20%3D%20%CE%B8%22%7C%20ON%5B%22on-policy%EF%BC%9AIS%20%E6%9D%83%E9%87%8D%20%3D%201%22%5D%0A%20%20Q%20--%3E%7C%22%E7%94%9F%E6%88%90%E4%B8%8E%E6%9B%B4%E6%96%B0%E5%B9%B6%E5%8F%91%EF%BC%8C%E7%89%88%E6%9C%AC%E8%90%BD%E5%90%8E%22%7C%20OFF%5B%22%E7%A6%BB%E7%AD%96%E7%95%A5%EF%BC%9A%E6%A2%AF%E5%BA%A6%E5%A4%B1%E7%9C%9F%22%5D%0A%20%20OFF%20--%3E%7C%22%E4%B8%8D%E8%A1%A5%E6%9D%83%E9%87%8D%22%7C%20B%5B%22%E5%B8%A6%E5%81%8F%E7%9A%84%E4%BC%B0%E8%AE%A1%EF%BC%9A%E9%9D%99%E9%BB%98%E5%87%BA%E9%94%99%22%5D%0A%20%20OFF%20--%3E%7C%22%E8%A1%A5%E6%88%AA%E6%96%AD%20IS%20%E6%9D%83%E9%87%8D%22%7C%20V%5B%22%E6%96%B9%E5%B7%AE%E4%B8%8A%E5%8D%87%EF%BC%9A%E8%B4%B5%E4%BD%86%E6%97%A0%E5%81%8F%22%5D%0A%20%20B%20--%3E%20RULE%5B%22%E9%93%81%E5%BE%8B%EF%BC%9A%E7%89%88%E6%9C%AC%E5%8F%B7%E9%9A%8F%E6%A0%B7%E6%9C%AC%E8%B5%B0%20%2B%20logprob%20%E7%94%9F%E6%88%90%E4%BE%A7%E5%BD%93%E5%9C%BA%E7%BC%93%E5%AD%98%22%5D%0A%20%20V%20--%3E%20RULE%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[o(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>rollout 引擎不负责打分与组批：奖励谁来算、经验怎么变成更新批次，是随后两课的事。它也不承诺收敛：引擎加速的是迭代成本，算法层的方差与偏差（<a href="/llm/reinforce-variance">REINFORCE 与方差</a>、<a href="/llm/grpo">GRPO</a> 的组基线选择）不因系统变快而消失。共置与分置没有免费解：显存峰值与墙钟结构随模型规模与序列长度变化，跨框架的默认值不可直接照搬。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>rollout 引擎的契约：提示批加权重版本进，序列、行为 logprob、结束原因出；本课程后课默认此接口。</li><li>三个设计决定：放置（共置/分置）、编排（单控制器数据流/多控制器计算）、权重同步（原子加版本号）。</li><li>行为 logprob 是接口里最值钱的一列：版本对齐靠它可验证，离策略偏差靠它可修正。</li><li>引擎只管迭代成本；算法的方差、偏差与奖励设计不归它管。</li><li>出处：Sheng 等，HybridFlow，EuroSys 2025；Kwon 等，vLLM，SOSP 2023；据各开源框架实现整理。</li></ul>',4))])}const b=n(d,[["render",C]]);export{_ as __pageData,b as default};
